-- Databricks Free Edition: bronze for 2014, same pattern as 05_phase2_full_load.sql
-- (2015). Part of the 5-year extension (2026-09-29) - each year gets its own bronze
-- table because each year's CSV has a different column set (279 columns for 2014;
-- see docs/scope_and_gaps.md for the full 454/359/336/279/330 breakdown). Silver unions
-- all 5 bronze tables together (see 03b_silver_multiyear.sql).

DROP TABLE IF EXISTS workspace.bronze.brfss_2014;

CREATE TABLE workspace.bronze.brfss_2014 AS
SELECT
  *,
  '2014.csv'                  AS _source_file,
  current_timestamp()           AS _loaded_at,
  'phase2-5yr-extension-20260929'                    AS _run_id
